import sys
import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse, urljoin

def get_final_url(url):
    try:
        response = requests.get(url, timeout=10, allow_redirects=True)
        return response.url
    except:
        return url

def extract_title(response):
    soup = BeautifulSoup(response.text, 'html.parser')
    title_tag = soup.find(lambda tag: tag.name.lower() == 'title')
    if title_tag and title_tag.string:
        return title_tag.string.strip()
    return '(no title)'

def main():
    urls = []
    for line in sys.stdin:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        urls.append(line)

    with open('link_report.html', 'w', encoding='utf-8') as f:
        f.write('<html><head><title>Link Report</title></head><body><table>\n')
        f.write('<tr><th>URL</th><th>Title</th><th>Final URL</th></tr>\n')

        for url in urls:
            final_url = get_final_url(url)
            response = requests.get(final_url, timeout=10)
            if response.status_code < 200 or response.status_code >= 300:
                title = '(error)'
            else:
                title = extract_title(response)

            f.write(f'<tr><td>{url}</td><td>{title}</td><td>{final_url}</td></tr>\n')

        f.write('</table></body></html>')

if __name__ == '__main__':
    main()
